sys_trigger.script:
(function() {
    try {
        var scanner = new CmdbHealthScanner();
        var result = scanner.scanAll('');
        var scanId = '';
        if (typeof result === 'object' && result.already_running) {
            gs.info('CMDB Health Daily Scan skipped — scan already in progress. Scan ID: ' + result.scan_id);
            return;
        }
        scanId = result;
        gs.info('CMDB Health Daily Scan completed. Scan ID: ' + scanId);
    } catch (e) {
        gs.error('CMDB Health Daily Scan failed: ' + e.message);
    }
})();
